import type { IAuthModuleService, MedusaContainer } from "@medusajs/framework/types"
import { ContainerRegistrationKeys, Modules } from "@medusajs/framework/utils"
import { ADDRESS_VOUCHING_PROVIDERS } from "../../lib/auth/providers"
import { likeLiteral } from "../../lib/db/like"
import { logger } from "../../lib/logging"

type Container = Pick<MedusaContainer, "resolve">

/**
 * What Medusa's auth service lists beyond its published types (2.21.2,
 * generated by MedusaService): operators on its rows.
 */
interface AuthRows {
  listProviderIdentities: (
    filters: Record<string, unknown>,
    config: { select: string[]; take: null }
  ) => Promise<{ auth_identity_id?: string | null }[]>
  listAuthIdentities: (
    filters: { id: string[] },
    config: { select: string[]; take: null }
  ) => Promise<{ id: string; app_metadata?: Record<string, unknown> | null }[]>
  listAuthVerifications: (
    filters: Record<string, unknown>,
    config: { select: string[]; take: null }
  ) => Promise<{ verified_at: Date | string | null }[]>
}

interface IdentityRow {
  id: string
  app_metadata?: Record<string, unknown> | null
  provider_identities?:
    ({ provider?: string | null; user_metadata?: Record<string, unknown> | null } | null)[] | null
}

const normalized = (email: string | null | undefined) => (email ?? "").trim().toLowerCase()

/** The customer's address when it is an account's: lowercased, or null. */
async function accountEmail(container: Container, customerId: string): Promise<string | null> {
  const { data } = await container.resolve(ContainerRegistrationKeys.QUERY).graph({
    entity: "customer",
    fields: ["id", "email", "has_account"],
    filters: { id: customerId },
  })
  const customer = data[0] as { email?: string | null; has_account?: boolean } | undefined
  const email = normalized(customer?.email)
  return customer?.has_account && email !== "" ? email : null
}

/** The sign-ins of this customer among these identities (app_metadata.customer_id). */
async function ownIdentities(auth: AuthRows, candidates: string[], customerId: string) {
  if (candidates.length === 0) {
    return []
  }
  const identities = await auth.listAuthIdentities(
    { id: [...new Set(candidates)] },
    { select: ["id", "app_metadata"], take: null }
  )
  return identities
    .filter((identity) => identity.app_metadata?.["customer_id"] === customerId)
    .map((identity) => identity.id)
}

async function confirmedEmail(container: Container, email: string, customerId: string) {
  const auth = container.resolve(Modules.AUTH) as unknown as AuthRows
  const address = { $ilike: likeLiteral(email) }
  const logins = await auth.listProviderIdentities(
    { provider: "emailpass", entity_id: address },
    { select: ["auth_identity_id"], take: null }
  )
  const own = await ownIdentities(
    auth,
    logins.flatMap((row) => (row.auth_identity_id ? [row.auth_identity_id] : [])),
    customerId
  )
  if (own.length === 0) {
    return false
  }
  const confirmations = await auth.listAuthVerifications(
    { entity_type: "email", entity_id: address, auth_identity_id: own },
    { select: ["verified_at"], take: null }
  )
  return confirmations.some(({ verified_at: verifiedAt }) => verifiedAt !== null)
}

/**
 * Whether the account's own e-mail sign-in has confirmed its address with
 * the mailed code, in that sign-in's session: an `AuthVerification` of
 * this customer's emailpass identity, for the customer's address,
 * verified. A code another identity confirmed for the address, or one this
 * identity confirmed for another address, proves nothing. The e-mail arm
 * of `provenCustomer`, and what a social sign-in needs of the account it
 * joins (adr/0037 §3).
 */
export async function confirmedByOwnLogin(
  container: Container,
  customerId: string
): Promise<boolean> {
  const email = await accountEmail(container, customerId)
  return email !== null && confirmedEmail(container, email, customerId)
}

/**
 * A social sign-in of this customer, from a provider that refuses an
 * unverified address (`ADDRESS_VOUCHING_PROVIDERS`), carrying the
 * customer's address in any case. The customer's identities are read and
 * compared here; a failure, or a row not this customer's, counts as no
 * proof.
 */
async function vouchedBySocial(container: Container, email: string, customerId: string) {
  try {
    // The auth service's own filter on the JSON column (Medusa's
    // `FilterableAuthIdentityProps.app_metadata`, the filter its
    // `removeCustomerAccountWorkflow` reads by): applied in the database.
    // Each row is checked again below all the same
    const identities: IdentityRow[] = await container
      .resolve<IAuthModuleService>(Modules.AUTH)
      .listAuthIdentities(
        { app_metadata: { customer_id: customerId } },
        { relations: ["provider_identities"], take: null }
      )
    return identities.some(
      (identity) =>
        identity.app_metadata?.["customer_id"] === customerId &&
        (identity.provider_identities ?? []).some((provider) => {
          const vouched = provider?.user_metadata?.["email"]
          return (
            ADDRESS_VOUCHING_PROVIDERS.includes(provider?.provider ?? "") &&
            typeof vouched === "string" &&
            normalized(vouched) === email
          )
        })
    )
  } catch (error) {
    // The error's name only: a database error may quote the query's values
    logger.warn({
      event: "account.social_proof_unread",
      error: error instanceof Error ? error.name : "unknown",
    })
    return false
  }
}

/**
 * Whether the customer has proven they own their address (security review
 * of ADR-0068 slice 1b, H1, and of PR #73): `has_account` alone is not
 * proof, since an e-mail registration has it before its address is
 * confirmed. Proven is the account's own e-mail sign-in having confirmed
 * it (`confirmedByOwnLogin`), or a social sign-in of the customer whose
 * provider vouched for it.
 */
export async function provenCustomer(container: Container, customerId: string): Promise<boolean> {
  const email = await accountEmail(container, customerId)
  if (email === null) {
    return false
  }
  return (
    (await confirmedEmail(container, email, customerId)) ||
    vouchedBySocial(container, email, customerId)
  )
}
